package pgx

import (
	"context"
	stdsql "database/sql"

	pgxv5 "github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"

	"github.com/eidon-go/core/contrib/sql"
)

// DBTX is what *pgxpool.Pool and pgx.Tx have in common; code generated by
// sqlc for pgx/v5 takes it (New(db DBTX) *Queries).
type DBTX interface {
	Exec(ctx context.Context, query string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, query string, args ...any) (pgxv5.Rows, error)
	QueryRow(ctx context.Context, query string, args ...any) pgxv5.Row
	CopyFrom(ctx context.Context, table pgxv5.Identifier, columns []string, src pgxv5.CopyFromSource) (int64, error)
	SendBatch(ctx context.Context, batch *pgxv5.Batch) pgxv5.BatchResults
}

// PgxQuerier is an sql.Querier — for Get, Select and Exec — that also
// passes for a DBTX: the transaction of the context or the pool. Native pgx
// code calls Exec/Query; the helpers call ExecContext/GetContext.
type PgxQuerier interface { //nolint:revive // pairs with sql.SQLQuerier: the world is in the name
	sql.Querier
	DBTX
}

// NewQuerier returns a PgxQuerier over dbtx that scans with scanner
// (DefaultScanner when nil).
func NewQuerier(dbtx DBTX, scanner Scanner) PgxQuerier {
	if scanner == nil {
		scanner = DefaultScanner()
	}

	return querier{DBTX: dbtx, scanner: scanner}
}

type querier struct {
	DBTX

	scanner Scanner
}

func (q querier) GetContext(ctx context.Context, dest any, query string, args ...any) error {
	rows, err := q.Query(ctx, query, args...)
	if err != nil {
		return err
	}

	return q.scanner.ScanOne(rows, dest) //nolint:wrapcheck // the scanner's error, as is
}

func (q querier) SelectContext(ctx context.Context, dest any, query string, args ...any) error {
	rows, err := q.Query(ctx, query, args...)
	if err != nil {
		return err
	}

	return q.scanner.ScanAll(rows, dest) //nolint:wrapcheck // the scanner's error, as is
}

// ExecContext runs Exec and adapts its command tag to sql.Result;
// LastInsertId returns ErrLastInsertIDUnsupported.
func (q querier) ExecContext(ctx context.Context, query string, args ...any) (stdsql.Result, error) {
	tag, err := q.Exec(ctx, query, args...)
	if err != nil {
		return nil, err
	}

	return result{tag: tag}, nil
}

type result struct{ tag pgconn.CommandTag }

func (result) LastInsertId() (int64, error) { return 0, ErrLastInsertIDUnsupported }

func (r result) RowsAffected() (int64, error) { return r.tag.RowsAffected(), nil }

// unstarted is the DBTX (and PoolIface) of a DB before Start: every call
// fails with ErrNotStarted.
type unstarted struct{}

func (unstarted) Exec(context.Context, string, ...any) (pgconn.CommandTag, error) {
	return pgconn.CommandTag{}, ErrNotStarted
}

func (unstarted) Query(context.Context, string, ...any) (pgxv5.Rows, error) {
	return nil, ErrNotStarted
}

func (unstarted) QueryRow(context.Context, string, ...any) pgxv5.Row { return errRow{} }

func (unstarted) CopyFrom(context.Context, pgxv5.Identifier, []string, pgxv5.CopyFromSource) (int64, error) {
	return 0, ErrNotStarted
}

func (unstarted) SendBatch(context.Context, *pgxv5.Batch) pgxv5.BatchResults { return errBatch{} }

func (unstarted) BeginTx(context.Context, pgxv5.TxOptions) (pgxv5.Tx, error) {
	return nil, ErrNotStarted
}

func (unstarted) Ping(context.Context) error { return ErrNotStarted }

func (unstarted) Close() {}

type errRow struct{}

func (errRow) Scan(...any) error { return ErrNotStarted }

type errBatch struct{}

func (errBatch) Exec() (pgconn.CommandTag, error) { return pgconn.CommandTag{}, ErrNotStarted }

func (errBatch) Query() (pgxv5.Rows, error) { return nil, ErrNotStarted }

func (errBatch) QueryRow() pgxv5.Row { return errRow{} }

func (errBatch) Tx() pgxv5.Tx { return nil }

func (errBatch) Close() error { return ErrNotStarted }
